  function adaptiveRecorder(key){return `<div class="g-speaking-tools"><div class="g-timer"><strong id="g-speech-timer">00:00</strong><span id="g-timer-label">准备与作答计时</span></div><div class="g-actions">${button('准备 30 秒','timer','data-seconds="30"')}${button('作答 90 秒','timer','data-seconds="90"')}${button('暂停计时','timer-stop')}</div><div class="g-recorder"><div class="g-actions">${button('开始录音','record-start','','red')}${button('结束录音','record-stop','disabled')}${button('下载录音','record-download',recordingBlob&&recordingTask===key?'':'disabled')}</div><p id="g-record-status" class="g-muted" aria-live="polite">允许麦克风后开始录音。提交本组时，录音会随本组一并提交。</p><div id="g-record-playback">${recordingUrl&&recordingTask===key?`<audio controls src="${esc(recordingUrl)}"></audio>`:''}</div></div></div>`;}
  function adaptivePage(){if(!adaptiveForceNew&&!savedAdaptive()&&!adaptiveCompletedResult){const last=[...normalized().diagnostics].reverse().find(item=>item.kind==='adaptive_diagnostic'&&item.adaptive?.complete);if(last){adaptiveCompletedResult={diagnostic:last,items:[...entryAssessmentBlocks.flatMap(block=>block.items),...adaptiveBlocks.flatMap(block=>block.items),...adaptiveManualItems],adaptive:last.adaptive};adaptiveEntry=false;}}if(adaptiveCompletedResult){adaptiveResultsPage();return;}const saved=savedAdaptive();if(!adaptiveSession&&saved)adaptiveSession=saved;if(adaptiveEntry||!adaptiveSession){layout(`${heading('能力测评','一次完成能力测评，题目以 B1 左右为主，可保存后继续。')}<section class="g-card g-assessment-entry"><div><span class="g-pill">可分次完成</span><h2>完成测评后，直接查看学习安排</h2><p>包含 6 道语境理解题、12 道阅读题和 12 道听力题，另有写作和口语任务。客观题自动批改，提交后直接进入个人学习计划。</p><div class="g-actions">${button(saved&&saved.version===2?'继续上次测评':'开始第一组','adaptive-start','','primary')}<span class="g-muted">不会的题可以留空；未作答的项目记为未完成。</span></div>${saved?`<p class="g-muted">${saved.version===2?`已保存 ${saved.history?.length||0} 组题。`:'本次测评题目已更新，请从第一组开始；之前的作答保留。'}</p>`:''}</div><ol><li><strong>各项分别判断</strong><p>按各项作答选出本轮重点，计划只安排当前需要练的内容。</p></li><li><strong>按顺序完成</strong><p>这是一套固定测评。完成后按具体错误安排有线索的短文、题型转换或原题练习。</p></li><li><strong>完成后给出具体练习</strong><p>列出材料名称、安排原因、提示使用和完成要求。</p></li></ol></section>`);return;}let next;try{next=nextAdaptiveBlock(adaptiveSession,adaptivePool());}catch(error){layout(`${heading('能力测评','测评记录暂时无法读取。')}${notice(error.message,'error')}${button('从第一组开始','adaptive-reset','','primary')}`);return;}if(next.complete){layout(`${heading('能力测评','本次题组已完成，保存结果后查看练习安排。')}<section class="g-card">${button('保存结果并查看安排','adaptive-start','','primary')}</section>`);return;}const block=next.block,key=`adaptive:${adaptiveSession.id}:${block.id}`,response=getUi().adaptiveResponseDraft,draft=response?.sessionId===adaptiveSession.id&&response.blockId===block.id?response:null,answers=draft?.answers||{},passages=[...new Set(block.items.map(item=>item.passage).filter(Boolean))],isSpeaking=block.skill==='speaking',previous=adaptiveSession.history.at(-1),previousSummary=previous?adaptiveResult(adaptiveSession,adaptivePool()).adaptive.skills[previous.block.skill]?.blocks?.find(item=>item.blockId===previous.block.id):null;layout(`${heading('能力测评',`${SKILL_NAMES[block.skill]||block.skill} · ${block.title}`,button('保存，稍后继续','adaptive-save'))}<div class="g-adaptive-progress"><span>已完成 ${next.progress.completedBlocks} 组</span><span>${['reading','listening'].includes(block.skill)?`本项第 ${next.progress.skillBlockIndex} / ${next.progress.maxSkillBlocks} 组`:'本项单独记录'}</span></div><div class="g-adaptive-reason" role="status"><strong>${previousSummary&&previousSummary.total?`上一组${esc(SKILL_NAMES[previous.block.skill])}：答对 ${esc(previousSummary.correct)} / ${esc(previousSummary.total)} 题`:'本组安排'}</strong><p>${esc(['writing','speaking'].includes(block.skill)?'作品会保存并提交给老师；客观题结果会直接生成当前练习安排。':next.reason)}</p></div><form id="g-adaptive" class="g-card" data-block="${esc(block.id)}" data-recording-key="${esc(key)}"><div class="g-card-top"><h2>${esc(block.title)}</h2><span id="g-adaptive-draft" class="g-muted" aria-live="polite">${draft?'本组作答已保存':''}</span></div><p class="g-muted">${esc(['writing','speaking'].includes(block.skill)?'按题目完成并提交，教师反馈会显示在作品记录中。自动批改暂未开通。':block.instructions||'先独立作答，提交后再查看结果。')}</p>${block.audioUrl&&safeAudio(block.audioUrl)?`<div class="g-audio-box"><h3>${esc(block.audioTitle||block.title)}</h3><audio controls preload="metadata" src="${esc(safeAudio(block.audioUrl))}"></audio><p class="g-muted">听完整录音，填写本组列出的题目。</p><label class="g-check"><input type="checkbox" name="audioUnavailable" ${draft?.audioUnavailable?'checked':''}>本次录音无法播放，听力记录为未完成</label></div>`:''}${passages.map(p=>`<article class="g-reading-text g-adaptive-passage">${paragraphs(p)}</article>`).join('')}${isSpeaking?adaptiveRecorder(key):''}${block.items.map((item,index)=>question({...item,passage:null},answers,index+1)).join('')}${isSpeaking?notice('文字提纲不能代替口语录音。暂时无法录音时，可以提交空白，本项保留待完成。'):notice('可以留空；未完成的项目会单独记录，完成测评后仍会给出练习安排。')}<div class="g-actions g-between"><span class="g-muted">${isSpeaking?'录音会在提交本组时上传。':'提交后保存本组作答，继续完成下一部分。'}</span><button type="submit" class="btn primary" data-g-submit>提交本组</button></div></form>`);}
  async function submitAdaptiveForm(form){const session=adaptiveSession,expectedOwner=ownerId,generation=disposedGeneration,view=renderToken;if(!session||session.userId!==expectedOwner)throw Error('当前测评记录不属于本账号，请重新打开。');clearTimeout(draftTimer);await savingDraft;if(expectedOwner!==accountId()||generation!==disposedGeneration)return;const current=nextAdaptiveBlock(session,adaptivePool()),block=current.block;if(!block||block.id!==form.dataset.block)throw Error('题组已更新，请重新打开。');const answers=collectAnswers(form),data=new FormData(form),audioUnavailable=block.skill==='listening'&&data.get('audioUnavailable')==='on';if(['writing','speaking'].includes(block.skill)){for(const item of block.items){const key=`${session.id}:${item.id}`,recordKey=`adaptive:${session.id}:${block.id}`,audio=block.skill==='speaking'&&recordingTask===recordKey&&recordingBlob?.size?recordingBlob:null,response=String(answers[item.id]||'').trim();if(block.skill==='speaking'&&!audio){answers[item.id]='';continue;}if(!response&&!audio)continue;const body=await prepareSubmission({skill:block.skill,title:item.title||block.title,prompt:item.prompt,response,text:response,materialId:`diagnostic:${item.id}`,taskId:`diagnostic:${item.id}`,stage:block.stage,diagnosticId:session.id,...(audio?{audioBlob:audio}:{})},key,'adaptiveSubmissionAttempts');if(expectedOwner!==accountId()||generation!==disposedGeneration)return;const sent=await host.submitWork(body);if(expectedOwner!==accountId()||generation!==disposedGeneration)return;const submissionId=(sent?.submission||sent)?.id;adaptiveSubmissionCache[key]=submissionId;await saveUi({adaptiveSubmissionIds:{...getUi().adaptiveSubmissionIds,[key]:submissionId}},expectedOwner);if(audio)answers[item.id]=response||'已提交口语录音，等待批改。';}}if(expectedOwner!==accountId()||generation!==disposedGeneration)return;const updated=submitAdaptiveBlock(session,block.id,answers,adaptivePool(),{userId:expectedOwner,audioUnavailable});await saveUi({adaptiveDraft:updated,adaptiveResponseDraft:null},expectedOwner);if(expectedOwner!==accountId()||generation!==disposedGeneration)return;adaptiveSession=updated;if(updated.status==='completed'){await finishAdaptive(updated,view);return;}if(view===renderToken){stopMedia();adaptivePage();}}
  async function finishAdaptive(session,view=renderToken){const expectedOwner=ownerId,generation=disposedGeneration,result=adaptiveResult(session,adaptivePool());if(!result.complete)throw Error('本次测评尚未完成，请继续当前题组。');const diagnostic=scoreDiagnostic(result.items,result.answers,{id:result.id,finishedAt:result.finishedAt,adaptive:result.adaptive,kind:'adaptive_diagnostic'});diagnostic.kind='adaptive_diagnostic';diagnostic.adaptive=result.adaptive;await save(recordDiagnostic(getProfile(),diagnostic));await saveUi({adaptiveDraft:null,adaptiveResponseDraft:null},expectedOwner);if(expectedOwner!==accountId()||generation!==disposedGeneration)return;adaptiveSession=session;adaptiveCompletedResult={diagnostic,items:result.items,adaptive:result.adaptive};adaptiveEntry=false;if(view===renderToken){stopMedia();location.hash='plan';}}
  function adaptiveResultsPage(){
    const result=adaptiveCompletedResult;if(!result)return;
    const path=personalPath(),rows=feedbackRows(result.diagnostic,result.items),groups=['foundation','reading','listening'];
    layout(`${heading('测评记录与练习安排','查看自己的答案、参考答案和题目解析。',link('开始今天的练习','growth','primary'))}${placementSummary(path,{all:true})}${groups.map(skill=>{const selected=rows.filter(row=>row.skill===skill),stats=summarizeAnswerFeedback(selected);return `<section class="g-card g-result-section"><div class="g-card-top"><h2>${SKILL_NAMES[skill]}作答</h2><span class="g-pill">${stats.answered?`${stats.correct} / ${stats.total} 题答对`:`${stats.total} 题未作答`}</span></div><p class="g-result-counts">${countsText(stats)}</p>${selected.filter(row=>row.status==='unanswered').length?`<p class="g-missing-answers">未完成：${selected.filter(row=>row.status==='unanswered').map(row=>`${esc(row.sourceTitle||'')} 第 ${esc(row.number)} 题${row.audioUnavailable?'（录音未能播放）':''}`).join('、')}。</p>`:''}${selected.map(row=>renderAnswerFeedback(row,{open:row.status==='wrong',nextTask:nextTaskFor(row,path)})).join('')}</section>`;}).join('')}<section class="g-card"><h2>写作与口语</h2><p>${rows.some(row=>row.skill==='writing'&&row.answered)?'写作已提交。':'尚未提交作文。'}${rows.some(row=>row.skill==='speaking'&&row.answered)?'口语录音已提交。':'尚未提交口语录音；文字提纲不计作口语作答。'}</p><div id="g-result-reviews" class="g-muted">正在读取批改记录…</div></section><div class="g-actions">${link('查看完整学习计划','plan')}</div>`);
    loadSubmissions('g-result-reviews');
  }
  function activeDiagnosticItems(){return diagnosticCheckId?confirmationChecks.find(check=>check.id===diagnosticCheckId)?.items||[]:diagnosticItems;}
  function activeDiagnosticDraft(){const draft=getUi().diagnosticDraft;return draft&&(draft.checkId||null)===diagnosticCheckId?draft:null;}
  function diagnosticPages() {const ordinary=activeDiagnosticItems().filter(item=>!item.audioGroup),audio=activeDiagnosticItems().filter(item=>item.audioGroup),pages=[];for(let i=0;i<ordinary.length;i+=5)pages.push(ordinary.slice(i,i+5));for(const key of new Set(audio.map(item=>item.audioGroup)))pages.push(audio.filter(item=>item.audioGroup===key));return pages;}
  function question(item, answers = {}, number = '') {const id=`g-q-${item.id}`,value=answers[item.id]??'';return `<fieldset class="g-question" data-question-id="${esc(item.id)}"><legend><span class="g-question-number">${esc(number)}</span>${esc(item.prompt)}</legend>${item.instructions||item.sourceInstruction?`<p class="g-item-instruction">${esc(item.instructions||item.sourceInstruction)}</p>`:''}${item.passage?`<div class="g-reading-text compact">${paragraphs(item.passage)}</div>`:''}${item.manual?`<textarea id="${esc(id)}" name="answer:${esc(item.id)}" rows="6" placeholder="写下回答或表达提纲。">${esc(value)}</textarea>`:item.options?.length?`<div class="g-options">${item.options.map((option,i)=>{const v=typeof option==='string'?option:option.value??String(i),label=typeof option==='string'?option:option.label;return `<label><input type="radio" name="answer:${esc(item.id)}" value="${esc(v)}" ${String(value)===String(v)?'checked':''}><span>${esc(label)}</span></label>`;}).join('')}</div>`:`<label class="g-text-answer"><span>${item.maxWords?`不超过 ${item.maxWords} 个词`:'填写答案'}</span><input id="${esc(id)}" name="answer:${esc(item.id)}" value="${esc(value)}" autocomplete="off"></label>`}</fieldset>`;}
  function diagnosticPage() {const saved=activeDiagnosticDraft();if(diagnosisPage<0 && saved && !diagnosisResult){diagnosisAnswers={...saved.answers};diagnosisStartedAt=saved.startedAt;}const pages=diagnosticPages();if(diagnosisResult){const result=diagnosisResult,items=activeDiagnosticItems(),savedRecord=(getUi().practiceResults||[]).find(record=>record.id===result.id)||result,rows=feedbackRows(savedRecord,items),stats=summarizeAnswerFeedback(rows),path=personalPath();layout(`${heading('练习结果',confirmationChecks.find(check=>check.id===diagnosticCheckId)?.title||'本次练习',link('查看今天的练习','growth','primary'))}<section class="g-card"><h2>本次作答</h2><p class="g-result-counts">${countsText(stats)}</p>${savedRecord.audioUnavailable?notice('本次录音未能播放，以下题目没有判分。'):''}${rows.map(row=>renderAnswerFeedback(row,{open:row.status==='wrong',nextTask:nextTaskFor(row,path)})).join('')}</section>${completionStrip(diagnosticCheckId)}${button('再次练习','diagnostic-reset')}`);return;}
    if(diagnosisPage<0){layout(`${heading(diagnosticCheckId?'日常练习':'能力测评',diagnosticCheckId?(confirmationChecks.find(check=>check.id===diagnosticCheckId)?.title||'完成当前题型练习并查看解析。'):'完成后查看具体练习，日常练习后会调整安排。')}<section class="g-card g-diagnostic-intro"><span class="g-pill">测评与练习安排</span><h2>${diagnosticCheckId?esc(confirmationChecks.find(check=>check.id===diagnosticCheckId)?.title||'日常练习'):'完成听、读、写、说测评'}</h2><p>${diagnosticCheckId?'先独立完成本组练习，交卷后查看解析。':'包含词句、阅读、听力与表达任务。遇到不会的题可以留空，按目前水平完成即可。'}</p><div class="g-diagnostic-sections">${['foundation',...SKILLS].filter(skill=>!diagnosticCheckId||activeDiagnosticItems().some(item=>item.skill===skill)).map(skill=>{const count=activeDiagnosticItems().filter(item=>item.skill===skill).length;return `<div><strong>${SKILL_NAMES[skill]}</strong><span>${count?`${count} 道任务`:'后续练习'}</span><small>${skill==='writing'||skill==='speaking'?'提交给老师':'客观题作答'}</small></div>`;}).join('')}</div>${notice(diagnosticCheckId?'先独立完成这一组题，交卷后查看参考答案和解析。':'听力部分请先检查耳机。写作与口语提交给老师；客观题交卷后显示作答结果。')}<div class="g-actions">${button(saved?'继续练习':'开始练习','diagnostic-start','','primary')}${saved?button('从第一组开始','diagnostic-reset'):''}</div></section>`);return;}
    const page=pages[diagnosisPage]||pages[0],firstAudio=page.find(item=>safeAudio(item.audioUrl)),offset=pages.slice(0,diagnosisPage).reduce((n,x)=>n+x.length,0);layout(`${heading(diagnosticCheckId?'日常练习':'能力测评',`第 ${diagnosisPage+1} / ${pages.length} 部分 · 按当前水平完成`)}<div class="g-progress" aria-label="测评进度"><span style="width:${(diagnosisPage+1)/pages.length*100}%"></span></div><form id="g-diagnostic" class="g-card">${firstAudio?`<div class="g-audio-box"><h2>${esc(firstAudio.audioTitle || '听力：志愿者面试')}</h2><p>先阅读题目，再播放录音。完成本组后统一提交。</p><audio controls preload="metadata" src="${esc(safeAudio(firstAudio.audioUrl))}"></audio><p class="g-muted">如果录音无法播放，请稍后重试，不要据此判断听力水平。</p><label class="g-check"><input type="checkbox" name="audioUnavailable" ${activeDiagnosticDraft()?.audioUnavailable?'checked':''}>本次录音无法播放，听力记录为未完成</label></div>`:''}${page.map((item,index)=>question(item,diagnosisAnswers,offset+index+1)).join('')}<div class="g-actions g-between">${button(diagnosisPage?'上一部分':'返回介绍','diagnostic-back')}<button type="submit" class="btn primary" data-g-submit>${diagnosisPage===pages.length-1?'提交练习':'保存并继续'}</button></div></form>`);}

  function readingAdaptation(version) {const detail=version.adaptation;if(!detail)return '';const changes=Array.isArray(detail.textChanges)?detail.textChanges:[detail.textChanges].filter(Boolean);const tasks=(Array.isArray(detail.taskChanges)?detail.taskChanges:[]).map(item=>typeof item==='string'?item:item.purpose||[item.from,item.to].filter(Boolean).join(' → '));return `<section class="g-card g-adaptation"><h2>本节训练</h2>${detail.sourceTitle?`<p>本节选用《${esc(detail.sourceTitle)}》的内容。</p>`:''}${changes.length?list(changes):''}${tasks.length?`<p>${[...new Set(tasks)].map(esc).join('；')}</p>`:''}<p class="g-muted">先阅读文章，再完成题目。提交后查看本题依据和题型改编说明。</p></section>`;}
  function readingPage(parts) {if(parts[1]==='vocabulary'&&vocabularySets.some(set=>set.id===parts[2])){vocabSet=parts[2];vocabularyPage();return;}if(parts[1])selectedReading=parts[1];if(parts[2])selectedVersion=parts[2];const unit=readingUnits.find(item=>item.id===selectedReading);if(!unit){const currentStage=buildSkillProfile(normalized()).reading.stage;layout(`${heading('分层阅读','同一主题，逐步增加文章长度、词汇范围和独立作答要求。',link('原版阅读题库','library'))}<div class="g-reading-grid">${readingUnits.map(item=>`<article class="g-card"><span class="g-pill">${esc(item.topic || '阅读训练')}</span><h2>${esc(item.titleCn || item.title)}</h2><p class="g-english-title">${esc(item.title)}</p><p>${item.versions.length} 个训练版本 · 保留原版练习入口</p><div class="g-actions">${item.versions.map(version=>link(stageName(version.stage),`foundation/${item.id}/${version.stage}`,version.stage===currentStage?'primary small':'secondary small')).join('')}</div></article>`).join('')}</div><section class="g-card"><h2>听力词汇与拼写</h2><p class="g-muted">按主题复习词义和拼写，再回到听力题中练习。</p><div class="g-actions">${vocabularySets.map(set=>button(set.title,'vocab-open',`data-set="${esc(set.id)}"`)).join('')}</div></section>`);if(vocabSet)vocabularyPage();return;}
    const version=unit.versions.find(item=>item.stage===selectedVersion)||unit.versions[0];selectedVersion=version.stage;const prior=normalized().evidence.some(item=>item.materialId===`${unit.id}:${version.stage}`);layout(`${heading(unit.titleCn||unit.title,`${stageName(version.stage)} · ${version.wordCount || wordCount(version.passage)} 词`,`${link('返回分层阅读','foundation')}${unit.originalId?button('练习原版','original-reading',`data-original="${esc(unit.originalId)}"`):''}`)}<div class="g-actions g-version-tabs">${unit.versions.map(v=>link(stageName(v.stage),`foundation/${unit.id}/${v.stage}`,v.stage===version.stage?'primary small':'secondary small')).join('')}</div>${readingResult?completionStrip(`${unit.id}:${version.stage}`):''}${readingResult?notice(`已保存：${readingResult.correct} / ${readingResult.total} 题正确。${readingResult.supported?'本次使用了提示，记为有提示训练。':readingResult.seenBefore?'本篇已有练习记录，记为复习。':'本次未使用提示。'}`,'success'):''}${readingAdaptation(version)}${shownSupports?lessonSteps({...unit,id:`${unit.id}:${version.stage}`,lessonSteps:version.lessonSteps||unit.lessonSteps},'reading'):''}<div class="g-reading-layout"><article class="g-card g-reading-text"><h2>${esc(version.title||unit.title)}</h2>${paragraphs(version.passage)}<div class="g-supports">${button(shownSupports?'收起提示':'查看词汇与分步练习','reading-supports')}${shownSupports?`${version.glossary?.length?`<dl class="g-glossary">${version.glossary.map(word=>`<div><dt>${esc(word.word)}</dt><dd>${esc(word.meaning)}</dd></div>`).join('')}</dl>`:''}${list(version.supports)}`:''}</div></article><form id="g-reading" class="g-card"><h2>阅读任务</h2>${version.questions.map((item,index)=>question(item,readingResult?.answers||{},index+1)).join('')}${readingResult?`<div class="g-answer-key">${readingResult.rows.map((row,index)=>renderAnswerFeedback(normalizeAnswerFeedback({id:row.item.id,response:readingResult.answers[row.item.id]||'',correct:row.correct,scored:true,skill:'reading',dimension:row.item.dimension,dimensionLabel:dimensionNames[row.item.dimension]||''},{...row.item,passage:version.passage},index),{open:!row.correct,nextTask:nextTaskFor({skill:'reading',dimension:row.item.dimension})})).join('')}</div>`:''}<button type="submit" class="btn primary" data-g-submit>${readingResult?'重新提交':'提交阅读任务'}</button></form></div>`);}
  function vocabularyPage() {const set=vocabularySets.find(item=>item.id===vocabSet);if(!set)return;layout(`${heading(set.title,'先看中文提示写英文，再检查拼写和例句。',button('返回训练','vocab-close'))}${lessonSteps(set,'listening')}<form id="g-vocabulary" class="g-card"><p>${esc(set.instructions||'填写单词。完成后查看参考拼写。')}</p>${typeof speechSynthesis!=='undefined'?'<p class="g-muted">可点击“听发音”做拼写练习。发音由浏览器朗读，提交后再查看单词和例句。</p>':''}<div class="g-vocab-grid">${set.items.map((item,index)=>`<label><span>${index+1}. ${esc(item.meaning)}</span>${typeof speechSynthesis!=='undefined'?button('听发音','vocab-audio',`data-index="${index}"`,'ghost small'):''}<input name="vocab:${index}" autocomplete="off" autocapitalize="none" spellcheck="false" value="${esc(vocabResult?.answers?.[index]||'')}">${vocabResult?`<strong class="${vocabResult.results[index]?'g-correct':'g-incorrect'}">${esc(item.word)}</strong><small>${esc(item.example||'')}</small>`:''}</label>`).join('')}</div><button class="btn primary" type="submit" data-g-submit>检查拼写</button>${vocabResult?notice(`本组 ${vocabResult.correct} / ${set.items.length} 个拼写正确。词汇复习不单独作为听力分数。`):''}</form>`);}

  function workPage(skill,parts) {const units=workUnits(skill);const measuredStage=buildSkillProfile(normalized())[skill].stage,currentStage=measuredStage==='foundation'?'supported':measuredStage;if(parts[1])selectedWork[skill]=parts[1];const unit=units.find(item=>item.id===selectedWork[skill])||units.find(item=>item.stage===currentStage)||units[0];if(!unit){layout(`${heading(SKILL_NAMES[skill]+'训练','训练材料正在准备。')}`);return;}selectedWork[skill]=unit.id;const draft=getUi().workDrafts?.[`${skill}:${unit.id}`]||{};const isSpeaking=skill==='speaking';layout(`${heading(isSpeaking?'口语练习':'写作练习',isSpeaking?'从高中生活出发，讲清楚自己的经历和想法。':'从句子到段落，再到完整文章。每次练习留下一次修改。',(host.guest?(isSpeaking?link('查看口语话题','textbooks/speaking'):''):link('查看学习计划','plan')))}${isSpeaking?renderSeasonalSpeakingCatalog(units):''}${!isSpeaking?`<div class="g-actions">${link('查看写作题库','writing')}${unit.textbook?link('查看本题与讲解',unit.textbook.route):''}</div>`:''}${unit.textbook&&isSpeaking?`<div class="g-card tb-textbook-source">${host.guest?'':`<p>${esc(unit.textbook.title)} · PDF 第 ${esc(unit.textbook.page)} 页</p>`}${unit.textbook.studentGuidance||unit.textbook.studentContext?`<p>${esc(unit.textbook.studentGuidance||unit.textbook.studentContext)}</p>`:''}${link(host.guest?'返回话题与提示':'回到教材学习页',unit.textbook.route,'secondary small')}${!host.guest&&unit.textbook.adaptationNote?`<details><summary>教材来源与说明</summary><p class="g-muted">${esc(unit.textbook.adaptationNote)}</p></details>`:''}</div>`:unit.textbook||host.guest?'':learningMap(skill)}${unit.writingGuidance?renderWritingGuidance(unit.writingGuidance):''}${renderTaskRubric(unit,skill,{selfCheck:host.guest})}<div class="g-work-layout"><aside class="g-card g-work-menu"><label>选择任务<select id="g-work-select" data-skill="${skill}">${(unit.textbook?[unit]:units.filter(item=>!item.textbook)).map(item=>`<option value="${esc(item.id)}" ${item.id===unit.id?'selected':''}>${esc(stageName(item.stage))} · ${esc(item.title)}</option>`).join('')}</select></label><span class="g-pill">${esc(stageName(unit.stage))} · ${unit.minutes||20} 分钟</span><h2>${esc(unit.title)}</h2>${isSpeaking?renderSeasonalSpeakingBadge(unit):''}<p class="g-work-prompt">${esc(unit.prompt)}</p>${unit.promptCn?`<p class="g-muted">${esc(unit.promptCn)}</p>`:''}${logicChain(unit)}${unit.questions?.length?list(unit.questions):''}${unit.instructions?.length?list(unit.instructions):''}${unit.followUps?.length?`<h3>${unit.seasonalPart===2?'Part 3':'继续想一想'}</h3>${list(unit.followUps)}`:''}<details><summary>需要提示时展开</summary>${list(unit.scaffold)}</details>${unit.model||unit.modelParagraph||unit.modelAnswer?`<details><summary>完成后再读参考表达</summary>${paragraphs(unit.model||unit.modelParagraph||unit.modelAnswer)}${unit.modelTranslation?`<div class="g-model-translation">${paragraphs(unit.modelTranslation)}</div>`:''}</details>`:''}</aside><form id="g-work" class="g-card" data-skill="${skill}" data-unit="${esc(unit.id)}"><div class="g-card-top"><h2>${isSpeaking?'我的表达':'我的草稿'}</h2><span id="g-draft-state" class="g-muted" aria-live="polite">${draft.updatedAt?'已保存草稿':''}</span></div>${isSpeaking?`<div class="g-speaking-tools"><div class="g-timer"><strong id="g-speech-timer">00:00</strong><span id="g-timer-label">准备与作答计时</span></div><div class="g-actions">${button('准备 1 分钟','timer', 'data-seconds="60"')}${button(`作答 ${unit.speakingSeconds||120} 秒`,'timer',`data-seconds="${unit.speakingSeconds||120}"`)}${button('暂停计时','timer-stop')}</div><div class="g-recorder"><div class="g-actions">${button('开始录音','record-start','','red')}${button('结束录音','record-stop','disabled')}${button('下载录音','record-download',recordingBlob&&recordingTask===unit.id?'':'disabled')}</div><p id="g-record-status" class="g-muted" aria-live="polite">录音只在点击“开始录音”并允许麦克风后开始，单次不超过 5 分钟。</p><div id="g-record-playback">${recordingUrl&&recordingTask===unit.id?`<audio controls src="${esc(recordingUrl)}"></audio>`:''}</div></div></div>`:''}<label class="g-work-editor">${isSpeaking?'表达提纲 / 录音文字（可选）':'正文'}<textarea name="response" rows="16" maxlength="16000" placeholder="${isSpeaking?'可以写关键词，也可以先录音。':'在这里开始写作…'}">${esc(draft.response||'')}</textarea></label><div class="g-editor-meta"><span id="g-word-count">${wordCount(draft.response)} 词</span><span>${unit.wordTarget?`建议 ${unit.wordTarget.min}–${unit.wordTarget.max} 词`:'先把意思说清楚，再逐步丰富表达。'}</span></div><fieldset class="g-self-check"><legend>${host.guest?'自我检查':'提交前检查'}</legend>${(unit.rubric||[]).map((rubric,index)=>`<label><input type="checkbox" name="check:${index}" ${draft.selfCheck?.includes(index)?'checked':''}><span><strong>${esc(rubric.name)}</strong><small>${esc(rubric.description)}</small></span></label>`).join('')}</fieldset><div class="g-actions"><button type="submit" class="btn primary" data-g-submit>${host.guest?'保存练习':'提交给老师'}</button><span class="g-muted">${host.guest?(isSpeaking?'提纲保存在当前浏览器，录音可下载。':'草稿保存在当前浏览器。'):'作品提交给老师；自动批改暂未开通。'}</span></div><p id="g-work-error" class="g-form-error" role="alert"></p></form></div>${!unit.writingGuidance?lessonSteps(unit,skill):''}${host.guest?'':`<section class="g-card"><h2>我的作品与反馈</h2><div id="g-submissions" class="g-muted">正在读取作品记录…</div></section>`}`);if(isSpeaking)bindSeasonalSpeakingCatalog(root);if(!host.guest)loadSubmissions('g-submissions',false,skill);}

  async function loadSubmissions(target,feedbackOnly=false,skill=null,poll=false) {const token=renderToken,expectedOwner=ownerId;if(!poll)submissionPollCount=0;try{const response=await host.getSubmissions?.();if(token!==renderToken||expectedOwner!==accountId())return;submissionsCache=Array.isArray(response)?response:response?.submissions||[];const matching=submissionsCache.filter(row=>(!skill||row.skill===skill)&&(!feedbackOnly||row.feedback||row.review?.comment||row.machineStatus));const changed=matching.some(row=>row.machineStatus==='completed'&&submissionStates.get(row.id)!=='completed');for(const row of matching)submissionStates.set(row.id,row.machineStatus);if(changed&&host.refreshGrowth){await host.refreshGrowth();if(token!==renderToken||expectedOwner!==accountId())return;}const rows=matching.slice(0,feedbackOnly?4:12),container=root?.querySelector(`#${target}`);if(!container)return;container.innerHTML=rows.length?rows.map(row=>`<article class="g-submission"><div class="g-card-top"><h3>${esc(row.title||row.prompt||'练习作品')}</h3><span class="g-pill ${row.machineStatus==='completed'||row.feedback?'green':''}">${row.machineStatus==='completed'?'已批改':row.feedback?'已复核':'已保存'}</span></div><p class="g-muted">${esc(SKILL_NAMES[row.skill]||row.skill)} · ${dateText(row.createdAt||row.submittedAt)}</p>${renderMachineReview(row,{admin:false}).replace(/data-account-action="submission-refresh"/g,'data-g-action="refresh-submissions"')}${row.feedback||row.review?.comment?`<div class="g-teacher-feedback"><h4>教师复核</h4><blockquote>${esc(row.feedback||row.review.comment)}</blockquote></div>`:''}${row.text||row.response?`<details><summary>查看已提交内容</summary><div class="g-submission-text">${paragraphs(row.text||row.response)}</div></details>`:''}${row.audioId?`<audio controls preload="none" src="/api/audio/${esc(row.audioId)}"></audio>`:''}${([...workUnits('writing'),...workUnits('speaking')].some(unit=>unit.id===(row.taskId||row.materialId))||/^textbook:[a-z0-9:-]+$/i.test(row.taskId||row.materialId||''))?button('按建议修改','revise',`data-submission="${esc(row.id)}"`,'secondary small'):''}</article>`).join(''):`<div class="g-empty"><h3>还没有提交作品</h3><p>完成写作或口语任务后，这里会显示批改状态和修改建议。</p></div>`;const pending=matching.some(row=>['queued','processing'].includes(row.machineStatus));clearTimeout(submissionPollTimer);if(pending&&submissionPollCount<15){submissionPollTimer=setTimeout(()=>{if(token!==renderToken||expectedOwner!==accountId())return;submissionPollCount++;loadSubmissions(target,feedbackOnly,skill,true);},4000);}else if(pending){container.insertAdjacentHTML('beforeend',notice('批改仍在进行，可以先继续其他练习，稍后刷新查看。'));}if(changed&&activeRoute==='plan'&&!document.activeElement?.closest?.('form')&&!busy){planPage();}}catch(error){if(token!==renderToken||expectedOwner!==accountId())return;const container=root?.querySelector(`#${target}`);if(container)container.textContent='作品记录暂时无法读取，请稍后刷新。';}}

  function semesterDates() {const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));const year=Number(parts.year),month=Number(parts.month);return {start:month>=9?`${year}-09-01`:month>=2?`${year}-02-01`:`${year-1}-09-01`,end:`${parts.year}-${parts.month}-${parts.day}`};}
  function reportPage() {reportDates ||= semesterDates();let report;try{report=buildSemesterReport(normalized(),reportDates);}catch(error){layout(`${heading('学习报告','按时间查看实际练习、作品与反馈。')}${reportFilters()}${notice(error.message,'error')}`);return;}layout(`${heading('学习报告','按日期汇总练习、作品和批改结果；未测项目显示“—”。',`${button('导出记录','report-export')}${button('打印 / 保存 PDF','report-print','','primary')}`)}${reportFilters()}<article id="g-report-content"><header class="g-print-brand"><strong>SLS · 学习报告</strong><span>育木成林，爱国荣校</span></header><section class="g-card g-report-intro"><div><h2>${esc(report.student.name||'我的学习记录')}</h2><p>${esc([report.student.grade,report.student.className].filter(Boolean).join(' · '))}</p><p>${esc(report.period.start)} — ${esc(report.period.end)}</p></div><div><span>个人目标</span><strong>${report.goals.overall?report.goals.overall.toFixed(1):'未设置'}</strong><p>目标日期 ${esc(report.goals.targetDate||'未设置')}</p></div></section><div class="g-report-totals">${[['完成练习',report.totals.attempts,'次'],['学习材料',report.totals.materials,'份'],['记录用时',Math.round(report.totals.minutes),'分钟'],['学习日期',report.totals.activeDays,'天']].map(([name,value,unit])=>`<div><span>${name}</span><strong>${value} <small>${unit}</small></strong></div>`).join('')}</div><section class="g-card"><h2>各项进展</h2><div class="g-table-wrap"><table><thead><tr><th>项目</th><th>训练阶段</th><th>练习次数</th><th>独立新材料</th><th>独立正确率</th><th>自动批改</th><th>教师复核</th></tr></thead><tbody>${SKILLS.map(skill=>{const row=report.skills[skill];return `<tr><th>${SKILL_NAMES[skill]}</th><td>${row.missingEvidence?'尚无记录':esc(row.stageName)}</td><td>${row.attempts}</td><td>${row.independentMaterials}</td><td>${percent(row.independentAccuracy)}</td><td>${row.machineReviews||0}</td><td>${row.teacherReviews}</td></tr>`;}).join('')}</tbody></table></div><p class="g-muted">使用过提示、重复材料和独立完成的新材料分别记录；正确率只反映本期练习表现。</p></section><section class="g-card"><h2>目标达成记录</h2><div class="g-table-wrap"><table><thead><tr><th>项目</th><th>个人目标</th><th>有效成绩</th><th>状态</th></tr></thead><tbody>${['overall',...SKILLS].map(skill=>{const row=report.attainment[skill];return `<tr><th>${skill==='overall'?'总分':SKILL_NAMES[skill]}</th><td>${row.target===null?'—':row.target.toFixed(1)}</td><td>${row.current===null?'—':row.current.toFixed(1)}</td><td>${esc(statusNames[row.status]||row.status)}</td></tr>`;}).join('')}</tbody></table></div><p class="g-muted">有效成绩由老师确认的模考或正式考试记录提供，不由短测正确率推算。</p></section><div class="g-report-skills">${SKILLS.map(skill=>{const row=report.skills[skill],next=nextTaskFor({skill});return `<section class="g-card"><h2>${SKILL_NAMES[skill]} · 下一步</h2>${row.dimensions.length?list(row.dimensions.map(d=>`${dimensionNames[d.dimension]||d.dimension}：答对 ${d.correct} / ${d.total} 题。`)):'<p>本期没有客观题作答。</p>'}${next?`<p>接下来练：${esc(next.title)}</p>`:''}${row.feedback.map(f=>`<blockquote><p>${esc(f.comment)}</p><cite>${esc(f.source==='machine'?'自动批改':f.reviewerName||'教师反馈')} · ${esc(f.date)}</cite></blockquote>`).join('')}${row.reviewPending?`<p>${row.reviewPending} 份作品等待批改。</p>`:''}</section>`;}).join('')}</div><section class="g-card"><h2>练习记录</h2>${report.totals.attempts?`<div class="g-table-wrap"><table><thead><tr><th>日期</th><th>项目</th><th>材料</th><th>完成方式</th><th>结果</th></tr></thead><tbody>${SKILLS.flatMap(skill=>report.skills[skill].timeline.map(row=>({...row,skill}))).sort((a,b)=>b.date.localeCompare(a.date)).map(row=>`<tr><td>${esc(row.date)}</td><td>${SKILL_NAMES[row.skill]}</td><td>${esc(materialTitle(row.materialId))}</td><td>${row.supported?'有提示':row.seenBefore?'复习':'独立新材料'}</td><td>${row.total?`${row.correct} / ${row.total}`:row.reviewed?'已反馈':'待反馈'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="g-muted">所选日期内还没有保存的练习。</p>'}</section>${dictationReport()}<p class="g-report-note">${esc(report.notice)}</p></article>`);}
  function dictationReport(){const report=summarizeDictation(getProfile(),reportDates);return `<section class="g-card"><h2>语料听写记录</h2><p>${report.sessions} 轮听写 · ${report.tracks} 段录音。以下为学生对照文本后自行记录，与教师评价分开统计。</p>${report.rows.length?`<div class="g-table-wrap"><table><thead><tr><th>日期</th><th>录音</th><th>轮次</th><th>自记结果</th></tr></thead><tbody>${report.rows.map(row=>`<tr><td>${esc(dateText(row.at))}</td><td>${esc(row.title)}</td><td>${row.kind}</td><td>${row.correct} / ${row.total}</td></tr>`).join('')}</tbody></table></div>`:'<p class="g-muted">所选日期内尚无听写记录。</p>'}</section>`;}
  function reportFilters() {return `<form id="g-report-filter" class="g-card g-report-filter g-no-print"><label>开始日期<input name="start" type="date" value="${esc(reportDates.start)}" required></label><label>结束日期<input name="end" type="date" value="${esc(reportDates.end)}" required></label><button type="submit" class="btn secondary">更新报告</button></form>`;}
  function materialTitle(id) {for(const rows of Object.values(allBanks())){if(Array.isArray(rows)){const found=rows.find(row=>row.id===id);if(found)return found.titleCn||found.title;}}return id;}

  function collectAnswers(form) {const answers={};for(const [name,value] of new FormData(form)){if(name.startsWith('answer:'))answers[name.slice(7)]=String(value);}return answers;}
  function currentRecordingTaskId(){return root?.querySelector('#g-adaptive')?.dataset.recordingKey||currentWork()?.unit.id||null;}
  function currentWork(form=root?.querySelector('#g-work')) {if(!form)return null;const skill=form.dataset.skill,units=workUnits(skill);return {form,skill,unit:units.find(item=>item.id===form.dataset.unit)};}
  function workDraft(form) {return {response:form.querySelector('[name=response]').value,selfCheck:[...form.querySelectorAll('[name^="check:"]:checked')].map(el=>Number(el.name.slice(6))),updatedAt:Date.now()};}
  function queueWorkDraft(form) {const work=currentWork(form);if(!work||ownerId!==accountId())return;const draft=workDraft(form),key=`${work.skill}:${work.unit.id}`,expectedOwner=ownerId,generation=disposedGeneration;draft.lastSubmissionId=getUi().workDrafts?.[key]?.lastSubmissionId||null;savingDraft=savingDraft.then(async()=>{if(expectedOwner!==accountId()||generation!==disposedGeneration)return;await saveUi({workDrafts:{...getUi().workDrafts,[key]:{...getUi().workDrafts?.[key],...draft}}},expectedOwner);if(root?.querySelector('#g-work')?.dataset.unit===work.unit.id){const el=root.querySelector('#g-draft-state');if(el)el.textContent='草稿已保存';}}).catch(()=>{if(expectedOwner!==accountId()||generation!==disposedGeneration)return;const el=root?.querySelector('#g-draft-state');if(el)el.textContent='草稿未保存，请重试';});return savingDraft;}
  function scheduleDraft(form) {clearTimeout(draftTimer);const status=root?.querySelector('#g-draft-state');if(status)status.textContent='正在保存草稿…';draftTimer=setTimeout(()=>queueWorkDraft(form),800);}

