  function stopRecording() {if(recorder?.state==='recording')recorder.stop();}
  async function openWorkPage(skill,parts) {
    const id=parts[1],isWriting=skill==='writing';
    const headingTitle=isWriting?'写作练习':'教材练习';
    const back=isWriting?link('返回写作题库','writing'):link('返回教材课程','textbooks');
    if(!id?.startsWith('textbook:')){workPage(skill,parts);return;}
    const token=renderToken,expectedOwner=ownerId,generation=disposedGeneration;
    try {
      let unit=trustedTextbookUnits.get(id);
      if(!unit){
        layout(`${heading(headingTitle,'正在读取任务…',back)}`);
        if(!host.loadTrustedTextbookTask)throw Error('教材任务暂时无法打开。');
        const payload=await host.loadTrustedTextbookTask(id);
        if(token!==renderToken||expectedOwner!==accountId()||generation!==disposedGeneration)return;
        unit=textbookTaskToUnit(payload);
        if(unit.id!==id||unit.skill!==skill)throw Error('本节任务与当前练习不一致，请从教材课程重新进入。');
        trustedTextbookUnits.set(id,unit);
      }
      if(unit.skill!==skill)throw Error('请从教材课程打开对应的练习。');
      workPage(skill,parts);
    } catch(error) {
      if(token!==renderToken||expectedOwner!==accountId()||generation!==disposedGeneration)return;
      layout(`${heading(headingTitle,'本次未能打开任务。',back)}${notice(isWriting?'暂时无法打开本题，请返回题库后重试。':error.message||'请稍后重试。','error')}`);
    }
  }
  async function render(route='growth') {destroy();if(ownerId!==null&&ownerId!==accountId())reset();ownerId=accountId();const parts=String(route).replace(/^#\/?/,'').split('/').map(part=>decodeURIComponent(part));const previousRoute=activeRoute;activeRoute=parts[0]||'growth';if(activeRoute==='foundation'&&(selectedReading!==parts[1]||selectedVersion!==parts[2])){selectedReading=parts[1]||null;selectedVersion=parts[2]||null;readingResult=null;shownSupports=false;supportsUsed=false;studyStartedAt=Date.now();}if(['writing','speaking'].includes(activeRoute))studyStartedAt=Date.now();if(activeRoute==='diagnostic'){const nextCheck=parts[1]==='check'?parts[2]||null:null;if(nextCheck!==diagnosticCheckId||previousRoute!=='diagnostic'){diagnosticCheckId=nextCheck;diagnosisPage=-1;diagnosisResult=null;diagnosisAnswers={};diagnosisStartedAt=null;}if(nextCheck&&!confirmationChecks.some(check=>check.id===nextCheck)){layout(`${heading('日常练习','没有找到这组练习题。',link('返回学习计划','plan'))}`);}else if(nextCheck)diagnosticPage();else adaptivePage();}else if(activeRoute==='plan')planPage();else if(activeRoute==='report')reportPage();else if(activeRoute==='foundation')readingPage(parts);else if(activeRoute==='writing'||activeRoute==='speaking')await openWorkPage(activeRoute,parts);else dashboard();root?.querySelector('h1')?.focus({preventScroll:true});}
  async function recordLegacy(record) {let profile=normalized();for(const evidence of evidenceFromLegacyRecord(record))profile=recordEvidence(profile,evidence);await save(profile);}
  return {render,destroy,reset,recordLegacy};
